[[ "$indexes" == 'PRIMARY:0:BTREE:environment_id:0,season_id:0,registry_version:0|uq_identity_registry_digest:0:BTREE:environment_id:0,season_id:0,registry_version:0,packet_digest:0' ]] || { echo 'telemetry_identity_registry indexes differ' >&2; exit 1; }
