[[ "$checks" == 'chk_identity_association_evidence:provenancebetween1and3andevidence_digest<>repeatchar0,32|chk_identity_association_identity:association_id<>0andaccount_token<>0andcontroller_tokenisnullorcontroller_token<>0|chk_identity_association_status:status=1andcontroller_tokenisnotnullorstatus=2andcontroller_tokenisnullorstatus=3|chk_identity_association_time:castvalid_from_utc_usecasunsigned<>9223372036854775808andvalid_through_utc_usecisnullorvalid_through_utc_usec>valid_from_utc_usec' ]] || { echo 'telemetry_identity_association checks differ' >&2; exit 1; }
foreign=$("${MYSQL[@]}" -e "SELECT CONCAT(k.constraint_name,':',k.ordinal_position,':',k.column_name,':',k.referenced_table_name,':',k.referenced_column_name,':',r.update_rule,':',r.delete_rule,':',BINARY k.referenced_table_schema=BINARY DATABASE()) FROM information_schema.key_column_usage k JOIN information_schema.referential_constraints r ON r.constraint_schema=k.constraint_schema AND r.constraint_name=k.constraint_name WHERE k.constraint_schema=DATABASE() AND k.table_name='telemetry_identity_association' AND k.referenced_table_name IS NOT NULL ORDER BY BINARY k.constraint_name,k.ordinal_position;" | paste -sd'|' -)
[[ "$foreign" == 'fk_identity_association_account:1:environment_id:telemetry_account_token:environment_id:RESTRICT:RESTRICT:1|fk_identity_association_account:2:season_id:telemetry_account_token:season_id:RESTRICT:RESTRICT:1|fk_identity_association_account:3:account_token:telemetry_account_token:account_token:RESTRICT:RESTRICT:1|fk_identity_association_registry:1:environment_id:telemetry_identity_registry:environment_id:RESTRICT:RESTRICT:1|fk_identity_association_registry:2:season_id:telemetry_identity_registry:season_id:RESTRICT:RESTRICT:1|fk_identity_association_registry:3:registry_version:telemetry_identity_registry:registry_version:RESTRICT:RESTRICT:1' ]] || { echo 'telemetry_identity_association foreign differ' >&2; exit 1; }
